const base64 = $input.first().json.stdout;

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(base64, 'base64'),
  'ConsultaMonitoramento.xlsx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
);

return [
  {
    json: {},
    binary: {
      data: binaryData
    }
  }
];

const items = $input.all();
const mapa = new Map();

function normalizarOC(valor) {
  return String(valor ?? "")
    .trim()
    .replace(/\.0+$/, "")
    .replace(/\D/g, "");
}

for (const item of items) {
  const dados = item.json;
  const dt = String(dados["DT"] ?? "").trim();

  if (!dt) continue;

  // O campo Ocorrências já deve conter apenas as OCs elegíveis,
  // pois este node vem depois de FILTRAR OCs POR SOLUÇÃO.
  const ocorrenciasTexto = String(dados["Ocorrências"] ?? "");

  const ocorrencias = (ocorrenciasTexto.match(/\d+/g) || [])
    .map(normalizarOC)
    .filter(oc => oc && oc !== "0");

  const tiposTexto = String(
    dados["Tipos Elegiveis para subir"] ?? ""
  );

  const tipos = tiposTexto
    .split(",")
    .map(tipo => tipo.trim())
    .filter(Boolean);

  // A NF vem da mesma linha do B2C que contém a solução elegível.
  const nfRemessa = String(
    dados["NF Remessa Elegivel"] ?? ""
  ).trim();

  const cidade = String(dados["Cidade"] ?? "").trim();
  const ehCTE = cidade !== "" &&
    cidade.normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toUpperCase()
      .trim() !== "SAO PAULO";

  if (!mapa.has(dt)) {
    mapa.set(dt, {
      DT: dt,
      OCs: [],
      OCsDetalhadas: []
    });
  }

  const registro = mapa.get(dt);

  for (let i = 0; i < ocorrencias.length; i++) {
    const oc = ocorrencias[i];
    const tipo = tipos[i] ?? "Tipo não informado";

    // Evita duplicar uma OC na consolidação.
    const existente = registro.OCsDetalhadas.find(
      entrada => entrada.OC === oc
    );

    if (!existente) {
      registro.OCs.push(oc);

      registro.OCsDetalhadas.push({
        OC: oc,
        Tipo: tipo,
        NFRemessa: nfRemessa,
        Cidade: cidade,
        CTE: ehCTE
      });
    } else {
      // Se já existe a OC, completa dados que eventualmente
      // não tenham sido preenchidos na primeira ocorrência.
      if (!existente.NFRemessa && nfRemessa) {
        existente.NFRemessa = nfRemessa;
      }

      if (
        existente.Tipo === "Tipo não informado" &&
        tipo !== "Tipo não informado"
      ) {
        existente.Tipo = tipo;
      }
    }
  }
}

return Array.from(mapa.values()).map(registro => ({
  json: registro
}));

const items = $input.all();

return items.map(item => {
  const dados = item.json;

  const dt = String(dados["Nº DT/CARGA"] ?? "")
    .trim()
    .replace(/^0+/, "");

  const oc = String(dados["Nº Ocorrência"] ?? "")
    .trim()
    .replace(/^0+/, "");

