const items = $input.all();

const mapa = new Map();

// Normaliza identificadores numéricos para evitar diferenças
// entre números, textos e valores vindos de planilhas.
function normalizarNumero(valor) {
  return String(valor ?? "")
    .trim()
    .replace(/\.0+$/, "")
    .replace(/\D/g, "");
}

for (const item of items) {
  const dados = item.json;

  const dt = normalizarNumero(dados.DT);

  if (!dt) {
    continue;
  }

  if (!mapa.has(dt)) {
    mapa.set(dt, {
      DT: dt,
      Frete: false,
      ExtraFretes: [],
      Registros: []
    });
  }

  const registro = mapa.get(dt);

  const oc = normalizarNumero(dados.OC);
  const tipo = String(dados.Tipo ?? "").trim();
  const status = String(dados.Status ?? "").trim();

  // Preserva os registros originais para consulta.
  registro.Registros.push({
    OC: oc,
    Tipo: tipo,
    Status: status
  });

  // FRETE
  if (tipo === "Frete" && status === "Importado") {
    registro.Frete = true;
  }

  // EXTRA FRETE
  if (tipo === "Extra Frete") {

    // OC vazia ou 0 não é uma ocorrência válida.
    // Assim, vale-pedágio não entra na comparação.
    if (!oc || oc === "0") {
      continue;
    }

    const existente = registro.ExtraFretes.find(
      extra => extra.OC === oc
    );

    if (!existente) {
      registro.ExtraFretes.push({
        OC: oc,
        Status: status || "Status não informado",
        Statuses: status ? [status] : []
      });

    } else {
      // Preserva os status encontrados para a mesma OC.
      if (
        status &&
        !existente.Statuses.includes(status)
      ) {
        existente.Statuses.push(status);
      }

      // Se houver Importado, ele será o status principal.
      // Outros status continuam registrados para conferência.
      if (status === "Importado") {
        existente.Status = "Importado";

      } else if (
        existente.Status !== "Importado" &&
        status
      ) {
        existente.Status = status;
      }
    }
  }
}

return Array.from(mapa.values()).map(registro => ({
  json: registro
}));

const items = $input.all();

function normalizarNumero(valor) {
  return String(valor ?? "")
    .trim()
    .replace(/\.0+$/, "")
    .replace(/\D/g, "");
}

function texto(valor) {
  return String(valor ?? "").trim();
}

return items.flatMap(item => {
  const dados = item.json;
  const dt = normalizarNumero(dados.DT);

  const ocsDetalhadas = Array.isArray(dados.OCsDetalhadas)
    ? dados.OCsDetalhadas
    : [];

  const ocsB2C = Array.isArray(dados.OCs)
    ? [...new Set(
        dados.OCs
          .map(normalizarNumero)
          .filter(oc => oc && oc !== "0")
      )]
    : [];

  // Relaciona cada OC ao seu tipo, NF de remessa e cidade.
  const mapaDetalhesOC = new Map(
    ocsDetalhadas.map(entrada => [
      normalizarNumero(entrada.OC),
      {
        Tipo: texto(entrada.Tipo),
        NFRemessa: texto(entrada.NFRemessa),
        Cidade: texto(entrada.Cidade),
        CTE: entrada.CTE === true
      }
    ])
  );

  const extraFretes = Array.isArray(dados.ExtraFretes)
    ? dados.ExtraFretes
        .map(extra => ({
          OC: normalizarNumero(extra.OC),
          Status: texto(extra.Status),
          Statuses: Array.isArray(extra.Statuses)
            ? extra.Statuses.map(texto).filter(Boolean)
            : []
        }))
        .filter(extra => extra.OC && extra.OC !== "0")
    : [];

  const mapaLupeon = new Map();

  for (const extra of extraFretes) {
    if (!mapaLupeon.has(extra.OC)) {
      mapaLupeon.set(extra.OC, []);
    }

    const statuses = extra.Statuses.length
      ? extra.Statuses
      : extra.Status
        ? [extra.Status]
        : [];

    const lista = mapaLupeon.get(extra.OC);

    for (const status of statuses) {
      if (!lista.includes(status)) {
        lista.push(status);
      }
    }
  }

  const freteLupeon = dados.Frete === true
    ? "Importado"
    : "Não encontrado";

  const listaExtraFretes = extraFretes
    .map(extra => {
      const statuses = mapaLupeon.get(extra.OC) ?? [];

      return `${extra.OC} (${
        statuses.length
          ? statuses.join(", ")
          : "Status não informado"
      })`;
    })
    .join(", ");

  const resultados = [];

  for (const oc of ocsB2C) {
    const existeNoLupeon = mapaLupeon.has(oc);

    const detalhesOC = mapaDetalhesOC.get(oc) ?? {
      Tipo: "Tipo não informado",
      NFRemessa: "",
      Cidade: "",
      CTE: false
    };

    const camposOC = {
      Tipo: detalhesOC.Tipo || "Tipo não informado",
      "NfRemessa": detalhesOC.NFRemessa,
      Cidade: detalhesOC.Cidade,
      CTE: detalhesOC.CTE
    };

    // Caso 1: OC não encontrada no Lupeon.
    if (!existeNoLupeon) {
      resultados.push({
        json: {
          DT: dt,
          Situacao: "VERIFICAR",
          TipoPendencia: "OC do B2C não localizada no Lupeon",
          OC: oc,
          ...camposOC,
          Detalhes:
            `A OC ${oc} consta no B2C para a DT ${dt}, ` +
            "mas não foi localizada nos extra fretes do Lupeon consultado.",
          "OCs B2C": ocsB2C.join(", "),
          "Frete Lupeon": freteLupeon,
          "Extra Fretes Lupeon": listaExtraFretes
        }
      });

      continue;
    }

    // Caso 2: OC encontrada, mas com status que exige conferência.
    const statuses = mapaLupeon.get(oc) ?? [];

    const statusProblematicos = statuses.filter(
      status => status !== "Importado"
    );

    if (
      statusProblematicos.length > 0 ||
      statuses.length === 0
    ) {
      const statusDescricao = statuses.length
        ? statuses.join(", ")
        : "Status não informado";

      resultados.push({
        json: {
          DT: dt,
          Situacao: "VERIFICAR",
          TipoPendencia: "Status do Lupeon para conferência",
          OC: oc,
          ...camposOC,
          Detalhes:
            `A OC ${oc} foi localizada no relatório do Lupeon, ` +
            `mas apresenta o seguinte status: ${statusDescricao}. ` +
            "Conferir o registro; esta pendência não significa que a OC esteja ausente.",
          "OCs B2C": ocsB2C.join(", "),
          "Frete Lupeon": freteLupeon,
          "Extra Fretes Lupeon": listaExtraFretes
        }
      });
    }
  }

  // Caso 3: nenhuma pendência encontrada para a DT.
  if (resultados.length === 0) {
    return [{
      json: {
        DT: dt,
        Situacao: "OK",
        TipoPendencia: "",
        OC: "",
        Tipo: "",
        "NfRemessa": "",
        Cidade: "",
        CTE: false,
        Detalhes: ocsB2C.length
          ? "Todas as OCs identificadas no B2C foram localizadas no Lupeon."
          : "Nenhuma OC válida identificada no B2C para comparar.",
        "OCs B2C": ocsB2C.join(", "),
        "Frete Lupeon": freteLupeon,
        "Extra Fretes Lupeon": listaExtraFretes
      }
    }];
  }

  return resultados;
});

const items = $input.all();

return items
  .filter(item => item.json.Situacao === "VERIFICAR")
  .map(item => {
    const dados = item.json;

    const tipoPendencia = String(dados.TipoPendencia ?? "");

    const resultadoLupeon =
      tipoPendencia === "OC do B2C não localizada no Lupeon"
        ? "Não localizada"
        : "Conferir status";

    const statusBuscaNF = String(dados.StatusBuscaNF ?? "");
    const alertaNF = String(dados.AlertaNF ?? "");

    let observacao =
      tipoPendencia === "OC do B2C não localizada no Lupeon"
        ? ""
        : String(dados.Detalhes ?? "");

    if (alertaNF) {
      observacao = observacao
        ? `${observacao} | ALERTA NF: ${alertaNF}`
        : `ALERTA NF: ${alertaNF}`;
    }

    return {
      json: {
        "DT": dados.DT ?? "",
        "OC a conferir": dados.OC ?? "",
        "Tipo": dados.Tipo ?? "Tipo não informado",
        "Resultado da busca no Lupeon": resultadoLupeon,
        "NF REMESSA": dados.NfRemessa ?? "",
        "Status NF COLETAS": statusBuscaNF,
        "OCs do B2C": dados["OCs B2C"] ?? "",
        "Observação": observacao
      }
    };
  });

const items = $input.all();

return items
  .filter(item => item.json.Situacao === "OK")
  .map(item => {
    const dados = item.json;
    return {
      json: {
        "DT": dados.DT ?? "",
        "Situação": dados.Situacao,
        "OCs do B2C": dados["OCs B2C"] ?? "",

      }
    };
  });

const items = $input.all();

// ==================================================
// 1. REGRAS DE NEGÓCIO
// ==================================================

// Soluções cujas OCs DEVEM ser lançadas no Lupeon.
const SOLUCOES_QUE_SOBEM = new Set([
  "RETORNO PARCIAL",
  "PAGAMENTO AUTORIZADO",
  "REENTREGA",
  "DEVOLUCAO PARCIAL",
  "RETORNO",
  "MERCADORIA RECEBIDA - COM ESTADIA"
]);

// Soluções cujas OCs NÃO devem ser lançadas no Lupeon.
const SOLUCOES_QUE_NAO_SOBEM = new Set([
  "MERCADORIA RECEBIDA",
  "COLETA FORA DE FLUXO",
  "DEVOLUCAO PARCIAL SEM CUSTO",
  "PROCESSO DE ENTREGA",
  "DEVOLUCAO PARCIAL FORA DE FLUXO",
  "REENTREGA SEM CUSTO",
  "COLETA",
  "PAGAMENTO NAO AUTORIZADO",
  "RETORNO SEM CUSTO",
  "DEVOLUCAO INTERCOMPANY - TRIANGULO"
]);

// ==================================================
// 2. FUNÇÕES AUXILIARES
// ==================================================

function normalizarTexto(valor) {
  return String(valor ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}

function normalizarNomeCampo(valor) {
  return normalizarTexto(valor).replace(/[^A-Z0-9]/g, "");
}

// Busca os campos sem depender de maiúsculas,
// minúsculas, acentos ou espaços no cabeçalho.
function buscarCampo(dados, nomesPossiveis) {
  const campos = Object.keys(dados);

  for (const nome of nomesPossiveis) {
    const procurado = normalizarNomeCampo(nome);

    const encontrado = campos.find(
      campo => normalizarNomeCampo(campo) === procurado
    );

    if (encontrado !== undefined) {
      return dados[encontrado];
    }
  }

  return undefined;
}

// Extrai os números das OCs e remove duplicadas.
function extrairOCs(valor) {
  const numeros = String(valor ?? "").match(/\d+/g) || [];

  return [
    ...new Set(
      numeros.filter(numero => numero !== "0")
    )
  ];
}

// ==================================================
// 3. PROCESSAR CADA REGISTRO DO B2C
// ==================================================

return items.map((item, indice) => {
  const dados = item.json;

  const dt = String(
    buscarCampo(dados, ["DT"]) ?? "DT não identificada"
  ).trim();

  const valorOCs = buscarCampo(dados, [
    "Ocorrências",
    "Ocorrencias"
  ]);

const valorStatus = buscarCampo(dados, [
  "Status_Ocorrências",
  "status_ocorrencia"
]);

  // Se os campos não existirem, interrompe a execução
  // para evitar uma conciliação incompleta.
if (
  valorOCs === undefined ||
  String(valorOCs ?? "").trim() === "" ||
  !String(valorOCs).match(/\d+/)
) {
  // Esta DT não possui nenhuma OC válida para comparar.
  return {
    json: {
      ...dados,
      "Ocorrências": "",
      "OCs originais": "",
      "OCs elegíveis para subir": "",
      "OCs descartadas pela solução": ""
    }
  };
}

  if (valorStatus === undefined) {
    throw new Error(
      `Item ${indice + 1}, DT ${dt}: campo "status_ocorrencia" não encontrado. ` +
      "Verifique se o node EXTRAIR DADOS B2C está trazendo a coluna BA."
    );
  }

  const ocsOriginais = extrairOCs(valorOCs);
  const textoStatus = String(valorStatus ?? "");

  // ==================================================
  // 4. ASSOCIAR CADA OC À SUA SOLUÇÃO
  // ==================================================

  const mapaSolucoes = new Map();

  // Os registros podem estar separados por <br>, <br/>
  // ou aparecer diretamente em sequência.
  const blocos = textoStatus
    .split(/<br\s*\/?>|(?=OC\s*:\s*\d+)/i)
    .map(bloco => bloco.trim())
    .filter(Boolean);

  for (const bloco of blocos) {
    const matchOC = bloco.match(/\bOC\s*:\s*(\d+)/i);

    if (!matchOC) {
      continue;
    }

    const oc = matchOC[1];

    if (!mapaSolucoes.has(oc)) {
      mapaSolucoes.set(oc, {
        solucoes: new Set(),
        semSolucao: false
      });
    }

    const registro = mapaSolucoes.get(oc);

    // Extrai a solução até o campo "Status NF".
    const matchSolucao = bloco.match(
      /\bSolu[cç][aã]o\s*:\s*([\s\S]*?)(?=\s*-\s*Status\s*NF\s*:|$)/i
    );

    if (!matchSolucao || !matchSolucao[1].trim()) {
      registro.semSolucao = true;
      continue;
    }

    const solucao = normalizarTexto(matchSolucao[1]);

    registro.solucoes.add(solucao);
  }

  // ==================================================
  // 5. VALIDAR SE TODAS AS OCs PODEM SER CLASSIFICADAS
  // ==================================================

  const ocsDaColuna = new Set(ocsOriginais);

  // Detecta OCs existentes no status que não aparecem
  // na lista original "Ocorrências".
  const ocsForaDaLista = [
    ...mapaSolucoes.keys()
  ].filter(oc => !ocsDaColuna.has(oc));

  if (ocsForaDaLista.length > 0) {
    throw new Error(
      `DT ${dt}: estas OCs aparecem em status_ocorrencia, ` +
      `mas não na coluna "Ocorrências": ${ocsForaDaLista.join(", ")}.`
    );
  }

  const ocsElegiveis = [];
  const ocsDescartadas = [];
  const tipoElegivel = [];

  for (const oc of ocsOriginais) {
    const registro = mapaSolucoes.get(oc);

    if (!registro) {
      throw new Error(
        `DT ${dt}: a OC ${oc} não possui registro correspondente ` +
        "em status_ocorrencia. Não é seguro classificá-la automaticamente."
      );
    }

    if (
      registro.semSolucao ||
      registro.solucoes.size === 0
    ) {
      throw new Error(
        `DT ${dt}: não foi possível identificar a solução da OC ${oc}.`
      );
    }

    if (registro.solucoes.size > 1) {
      throw new Error(
        `DT ${dt}: a OC ${oc} apareceu com soluções diferentes: ` +
        `${[...registro.solucoes].join(" / ")}. Confira o B2C.`
      );
    }

    const solucao = [...registro.solucoes][0];

    // A OC deve continuar no fluxo.
    if (SOLUCOES_QUE_SOBEM.has(solucao)) {
      ocsElegiveis.push(oc);
      tipoElegivel.push(solucao);
      continue;
    }

    // A OC deve ser descartada da conciliação.
    if (SOLUCOES_QUE_NAO_SOBEM.has(solucao)) {
      ocsDescartadas.push(`${oc} (${solucao})`);
      continue;
    }

    // Solução nova ou não mapeada: não ignorar silenciosamente.
    throw new Error(
      `DT ${dt}: solução não cadastrada para a OC ${oc}: ` +
      `"${solucao}". Adicione-a às regras antes de continuar.`
    );
  }

  // ==================================================
  // 6. DEVOLVER OS DADOS FILTRADOS
  // ==================================================

  return {
    json: {
      ...dados,

      // Este é o campo lido pelo node CONSOLIDAR DADOS B2C.
      // Agora contém somente as OCs que devem subir.
      "Ocorrências": ocsElegiveis.join(" / "),

      // Campos auxiliares para conferência durante os testes.
      "OCs originais": ocsOriginais.join(", "),
      "OCs elegíveis para subir": ocsElegiveis.join(", "),
      "Tipos Elegiveis para subir": tipoElegivel.join(", "),
      "OCs descartadas pela solução": ocsDescartadas.join(", ")
    }
  };
});

const items = $input.all();

const SOLUCOES_QUE_SOBEM = new Set([
  "RETORNO PARCIAL",
  "PAGAMENTO AUTORIZADO",
  "REENTREGA",
  "DEVOLUCAO PARCIAL",
  "RETORNO"
]);

function normalizarTexto(valor) {
  return String(valor ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .trim();
}

function extrairOCs(texto) {
  return [...new Set(
    (String(texto ?? "").match(/\d+/g) || [])
      .filter(oc => oc !== "0")
  )];
}

return items.map(item => {
  const dados = item.json;

  const cidade = normalizarTexto(dados["Cidade"]);
  const nfRemessa = String(dados["NF Remessa"] ?? "").trim();

  const ocs = extrairOCs(dados["Ocorrências"]);
  const statusTexto = String(dados["Status_Ocorrências"] ?? "");

  const tiposElegiveis = [];
  const ocsElegiveis = [];

  // Identifica a solução de cada OC descrita no status.
  const registros = statusTexto.match(
    /OC:\s*\d+[\s\S]*?(?=OC:\s*\d+|$)/gi
  ) || [];

  for (const registro of registros) {
    const ocMatch = registro.match(/OC:\s*(\d+)/i);
    const solucaoMatch = registro.match(/Solução:\s*([^-]*?)(?=\s*-\s*Status NF:|$)/i);

    if (!ocMatch || !solucaoMatch) continue;

    const oc = ocMatch[1];
    const solucao = normalizarTexto(solucaoMatch[1]);

    if (SOLUCOES_QUE_SOBEM.has(solucao)) {
      ocsElegiveis.push(oc);
      tiposElegiveis.push(solucao);
    }
  }

  // Mantém somente as OCs elegíveis que também constam
  // no campo Ocorrências desta linha do B2C.
  const ocsElegiveisDaLinha = ocsElegiveis.filter(
    oc => ocs.includes(oc)
  );

  return {
    json: {
      ...dados,
      Cidade_Normalizada: cidade,
      "OCs elegíveis para subir": ocsElegiveisDaLinha.join(", "),
      "Tipos Elegiveis para subir": tiposElegiveis.join(", "),

      // Nesta etapa, a NF é associada à OC elegível da própria linha.
      "NF Remessa Elegivel": ocsElegiveisDaLinha.length > 0
        ? nfRemessa
        : "",

      "É CTE": cidade !== "" && cidade !== "SAO PAULO"
    }
  };
});

const raw = $input.first().json.stdout;

if (!raw) {
  throw new Error('O node LER COLETAS não retornou dados em stdout.');
}

let rows;

try {
  rows = JSON.parse(raw);
} catch (error) {
  throw new Error(
    'Não foi possível interpretar o JSON de COLETAS. Verifique a saída do Execute Command.'
  );
}

if (!Array.isArray(rows)) {
  rows = [rows];
}

return rows
  .filter(row => {
    const dt = String(row.DT ?? '').trim();
    const cliente = String(row.Cliente ?? '').trim();

    // Ignora cabeçalhos, linhas vazias e separadores.
    return /^\d+$/.test(dt) && cliente !== '';
  })
  .map(row => ({
    json: {
      origem: 'COLETAS',
      DT: String(row.DT).trim(),
      Cliente: String(row.Cliente ?? '').trim(),
      Nota: String(row.Nota ?? '').trim(),
      Aba: String(row.Aba ?? '').trim(),
      Linha: row.Linha
    }
  }));

const itens = $input.all();

return itens
  .filter(item => {
    const dados = item.json;

    const cidade = String(dados.Cidade ?? '')
      .trim()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toUpperCase();

    const dt = String(dados.DT ?? '').trim();

    return cidade === 'SAO PAULO' && /^\d+$/.test(dt);
  })
  .flatMap(item => {
    const dados = item.json;
    const dt = String(dados.DT).trim();

    const ocorrencias = String(dados.Status_Ocorrências ?? '')
      .split('\n');

    return ocorrencias
      .map(linha => {
        const ocMatch = linha.match(/OC:\s*(\d+)/i);
        const tipoMatch = linha.match(/Solução:\s*(.*?)\s*-\s*Status NF:/i);

        if (!ocMatch || !tipoMatch) return null;

        return {
          json: {
            ...dados,
            origem: 'B2C',
            DT: dt,
            OC: ocMatch[1].trim(),
            Tipo: tipoMatch[1].trim().toUpperCase()
          }
        };
      })
      .filter(item => item !== null);
  });

const itens = $input.all().map(item => item.json);

const b2c = itens.filter(item => item.origem === 'B2C');
const coletas = itens.filter(item => item.origem === 'COLETAS');

const porDT = new Map();

for (const linha of coletas) {
  const dt = String(linha.DT ?? '').trim();

  if (!dt) continue;

  if (!porDT.has(dt)) {
    porDT.set(dt, []);
  }

  porDT.get(dt).push(linha);
}

function extrairReferencias(nota) {
  return String(nota ?? '')
    .split('/')
    .map(parte => parte.trim())
    .filter(parte =>
      /[A-Za-z]/.test(parte) &&
      /[\d?]/.test(parte)
    );
}

function prefixoEsperado(tipo) {
  const t = String(tipo ?? '').trim().toUpperCase();

  if (t === 'PAGAMENTO AUTORIZADO') return 'D';
  if (t === 'REENTREGA') return 'R';

  return null;
}

return b2c.map(registro => {
  const dt = String(registro.DT ?? '').trim();
  const oc = String(registro.OC ?? '').trim();
  const tipo = String(registro.Tipo ?? '').trim().toUpperCase();
  const prefixo = prefixoEsperado(tipo);

  const linhas = porDT.get(dt) ?? [];

  const todasReferencias = [
    ...new Set(
      linhas.flatMap(linha => extrairReferencias(linha.Nota))
    )
  ];

  const referenciasCompativeis = prefixo
    ? todasReferencias.filter(ref =>
        ref.toUpperCase().startsWith(prefixo)
      )
    : [];

  let status;

  if (linhas.length === 0) {
    status = 'DT NÃO ENCONTRADA';
  } else if (prefixo === null) {
    status = 'TIPO SEM REGRA DE PREFIXO — CONFERIR';
  } else if (referenciasCompativeis.some(ref => ref.includes('?'))) {
    status = 'REVISAR — REFERÊNCIA INCOMPLETA';
  } else if (referenciasCompativeis.length > 1) {
    status = 'MÚLTIPLAS NOTAS — CONFERIR';
  } else if (referenciasCompativeis.length === 1) {
    status = 'NF ENCONTRADA';
  } else if (todasReferencias.length > 0) {
    status = 'SEM REFERÊNCIA COMPATÍVEL — COMUNICAR EQUIPE';
  } else {
    status = 'SEM NF ADICIONAL — COMUNICAR EQUIPE';
  }

  return {
    json: {
      ...registro,
      DT: dt,
      OC: oc,
      Tipo: tipo,
      PrefixoEsperado: prefixo ?? 'SEM REGRA',
      NF_Referencias_Originais: todasReferencias,
      NF_Candidatas: referenciasCompativeis,
      Quantidade_NF: referenciasCompativeis.length,
      Status_NF: status,
      COLETAS_Encontradas: linhas.map(linha => ({
        Aba: linha.Aba,
        Linha: linha.Linha,
        Nota: linha.Nota,
        Cliente: linha.Cliente
      }))
    }
  };
});

return $input.all().map(item => {
  const d = item.json;

  const candidatas = Array.isArray(d.NF_Candidatas)
    ? [...new Set(d.NF_Candidatas)]
    : [];

  const ehCTE = d.CTE === true;

  const cidade = String(d.Cidade ?? '')
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase();

  const ehSaoPaulo = cidade === 'SAO PAULO';

  const statusNF = String(d.Status_NF ?? '').trim();
  const nfRemessaOriginal = String(d.NfRemessa ?? '').trim();

  const nfEncontrada =
    !ehCTE &&
    statusNF === 'NF ENCONTRADA' &&
    candidatas.length === 1 &&
    !candidatas[0].includes('?')
      ? candidatas[0]
      : '';

  let nfRemessa;
  let statusBuscaNF;
  let alertaNF;

  if (ehCTE) {
    nfRemessa = nfRemessaOriginal;

    if (nfRemessaOriginal) {
      statusBuscaNF = 'CTE — NF REMESSA PRESERVADA';
      alertaNF = '';
    } else {
      statusBuscaNF = 'CTE — NF REMESSA AUSENTE NA ORIGEM';
      alertaNF =
        'CTE sem NF Remessa informada no B2C. Conferir manualmente na COLETAS e validar qual nota corresponde à ocorrência.';
    }

  } else if (ehSaoPaulo) {
    nfRemessa = nfEncontrada;

    if (nfEncontrada) {
      statusBuscaNF = 'NF ENCONTRADA NA COLETAS';
      alertaNF = '';

    } else if (
      statusNF === 'SEM REFERÊNCIA COMPATÍVEL — COMUNICAR EQUIPE'
    ) {
      statusBuscaNF = 'REFERÊNCIA INCOMPATÍVEL';
      alertaNF =
        'COLETAS possui referência, mas não com o prefixo esperado. Comunicar a equipe.';

    } else if (
      statusNF === 'SEM NF ADICIONAL — COMUNICAR EQUIPE' ||
      statusNF === 'DT NÃO ENCONTRADA'
    ) {
      statusBuscaNF = 'NF NÃO ENCONTRADA NA COLETAS';
      alertaNF =
        'Não foi localizada referência de NF na COLETAS. Conferir com a equipe se a nota foi criada.';

    } else if (
      statusNF === 'REVISAR — REFERÊNCIA INCOMPLETA'
    ) {
      statusBuscaNF = 'REFERÊNCIA INCOMPLETA';
      alertaNF =
        'A referência encontrada está incompleta. Conferir com a equipe.';

    } else if (
      statusNF === 'MÚLTIPLAS NOTAS — CONFERIR'
    ) {
      statusBuscaNF = 'MÚLTIPLAS NOTAS';
      alertaNF =
        'Foram encontradas múltiplas referências. Conferir com a equipe.';

    } else {
      statusBuscaNF = 'CONFERIR — NF NÃO CONFIRMADA NA COLETAS';
      alertaNF =
        'Não foi possível confirmar uma NF compatível. Conferir com a equipe.';
    }

  } else {
    nfRemessa = nfEncontrada || nfRemessaOriginal;

    statusBuscaNF = nfEncontrada
      ? 'NF CANDIDATA ENCONTRADA'
      : candidatas.length > 1
        ? 'MÚLTIPLAS NOTAS — CONFERIR'
        : 'SEM NF ÚNICA — CONFERIR';

    alertaNF = '';
  }
    return {
    json: {
      ...d,
      NfRemessa: nfRemessa,
      StatusBuscaNF: statusBuscaNF,
      AlertaNF: alertaNF
    }
  };
});

const itens = $input.all().map(item => item.json);
const grupos = new Map();

for (const item of itens) {
  const dt = String(item.DT ?? '').trim();
  const oc = String(item.OC ?? '').trim();
  const tipo = String(item.Tipo ?? '').trim();

  if (!dt || !oc) continue;

  const chave = `${dt}::${oc}::${tipo}`;

  if (!grupos.has(chave)) {
    grupos.set(chave, {
      DT: dt,
      OC: oc,
      Tipo: tipo,
      PrefixoEsperado: item.PrefixoEsperado ?? 'SEM REGRA',
      NF_Candidatas: [],
      NF_Referencias_Originais: [],
      COLETAS_Encontradas: [],
      StatusOriginais: []
    });
  }

  const grupo = grupos.get(chave);

  grupo.NF_Candidatas.push(...(item.NF_Candidatas ?? []));
  grupo.NF_Referencias_Originais.push(
    ...(item.NF_Referencias_Originais ?? [])
  );
  grupo.COLETAS_Encontradas.push(
    ...(item.COLETAS_Encontradas ?? [])
  );

  if (item.Status_NF) {
    grupo.StatusOriginais.push(item.Status_NF);
  }
}

return [...grupos.values()].map(grupo => {
  const candidatas = [...new Set(grupo.NF_Candidatas)];
  const originais = [...new Set(grupo.NF_Referencias_Originais)];

  const incompleta = candidatas.some(nf => nf.includes('?'));

  let status;

  if (incompleta) {
    status = 'REVISAR — REFERÊNCIA INCOMPLETA';
  } else if (candidatas.length > 1) {
    status = 'MÚLTIPLAS NOTAS — CONFERIR';
  } else if (candidatas.length === 1) {
    status = 'NF ENCONTRADA';
  } else if (
    grupo.StatusOriginais.includes(
      'SEM REFERÊNCIA COMPATÍVEL — COMUNICAR EQUIPE'
    )
  ) {
    status = 'SEM REFERÊNCIA COMPATÍVEL — COMUNICAR EQUIPE';
  } else if (
    grupo.StatusOriginais.includes(
      'SEM NF ADICIONAL — COMUNICAR EQUIPE'
    )
  ) {
    status = 'SEM NF ADICIONAL — COMUNICAR EQUIPE';
  } else if (
    grupo.StatusOriginais.includes('DT NÃO ENCONTRADA')
  ) {
    status = 'DT NÃO ENCONTRADA';
  } else if (
    grupo.StatusOriginais.includes(
      'TIPO SEM REGRA DE PREFIXO — CONFERIR'
    )
  ) {
    status = 'TIPO SEM REGRA DE PREFIXO — CONFERIR';
  } else {
    status = 'SEM NF ADICIONAL — CONFERIR';
  }

  return {
    json: {
      DT: grupo.DT,
      OC: grupo.OC,
      Tipo: grupo.Tipo,
      PrefixoEsperado: grupo.PrefixoEsperado,
      NF_Candidatas: candidatas,
      NF_Referencias_Originais: originais,
      Quantidade_NF: candidatas.length,
      Status_NF: status,
      COLETAS_Encontradas: grupo.COLETAS_Encontradas
    }
  };
});
